Lemma chunk_of_AXImg : forall m ac,
  AXImg m ->
  (rw_bytes_b asegs (fst ac) (flat_map le8z (snd ac))
   && (((AXRELRO_LO <=? fst ac) && (fst ac + 8 * Z.of_nat (length (snd ac)) <=? AXRELRO_HI))
       || ((AXDATA_LO <=? fst ac) && (fst ac + 8 * Z.of_nat (length (snd ac)) <=? AXDATA_HI))))%Z = true ->
  rw_cells asegs m (fst ac) (wcells (snd ac)).
Proof.
  intros m [A zs] [P1 P2] Hb. cbn [fst snd] in *.
  apply andb_prop in Hb. destruct Hb as [RB R].
  unfold AXRELRO_LO, AXRELRO_HI, AXDATA_LO, AXDATA_HI in *.
  apply (wcells_of_image m A zs); [| exact RB | |].
  - intros a Ha. apply Bool.orb_prop in R. destruct R as [R|R]; apply andb_prop in R; destruct R as [R1 R2];
      apply Z.leb_le in R1; apply Z.leb_le in R2; [apply P1 | apply P2]; lia.
  - apply Bool.orb_prop in R. destruct R as [R|R]; apply andb_prop in R; destruct R as [R1 R2]; apply Z.leb_le in R1; lia.
  - apply Bool.orb_prop in R. destruct R as [R|R]; apply andb_prop in R; destruct R as [R1 R2]; apply Z.leb_le in R2; lia.
Qed.

