(* [comment removed for export] *)
Definition AFieldTabZero (m : mem) : Prop :=
  rw_cells asegs m AG_FIELD_TABLE [CB 3448 (zeros 3448)] /\ rw_cells asegs m AG_FIELD_TABLE_GUARD [CB 8 (zeros 8)].

(* [comment removed for export] *)
Definition aft_local (FT : mem -> Prop) : Prop :=
  forall m m', FT m -> (forall a, AXH_LO <= a < AXH_HI -> m' (wa a) = m (wa a)) -> FT m'.

(* [comment removed for export] *)
Definition AHStat (FT : mem -> Prop) (m : mem) : Prop :=
  (exists hb : bool, AHttpCat m hb) /\ (AFieldTabZero m \/ FT m).

Lemma AHttpCat_agree : forall m m' hb,
  AHttpCat m hb -> (forall a, AXH_LO <= a < AXH_HI -> m' (wa a) = m (wa a)) -> AHttpCat m' hb.
Proof.
  intros m m' hb [C1 C2] AG. split.
  - eapply rw_cells_agree; [exact C1|]. intros a Ha. apply AG.
    assert (Z.of_nat (cells_size (AHttpCatCells hb)) = 56) by (destruct hb; reflexivity).
    unfold AXH_LO, AXH_HI, AG_HTTP_CAT in *. lia.
  - eapply rw_cells_agree; [exact C2|]. intros a Ha. apply AG.
    assert (Z.of_nat (cells_size (AHttpCatGuardCells hb)) = 8) by (destruct hb; reflexivity).
    unfold AXH_LO, AXH_HI, AG_HTTP_CAT_GUARD in *. lia.
Qed.

Lemma AFieldTabZero_agree : forall m m',
